package platform

import (
	"html/template"
	"time"
)

var reportTemplate = template.Must(template.New("report").Funcs(template.FuncMap{"cnTime": func(t time.Time) string { return t.In(reportZone).Format("2006-01-02 15:04") }}).Parse(`<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.Report.Title}}</title>
<style>body{font-family:system-ui,-apple-system,sans-serif;background:#f3f6fc;color:#182944;margin:0;line-height:1.75}main{max-width:1160px;margin:auto;padding:40px 24px}header{padding:36px;background:#142e55;color:white;border-radius:20px}h1{font-size:32px;line-height:1.4;margin:14px 0}h2{font-size:22px;margin:0 0 18px}h3{font-size:16px}small,.muted{color:#708098}header small{color:#b5cae9}.kpis,.charts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:24px 0}.kpi,section{background:white;border:1px solid #e1e8f2;border-radius:14px;padding:24px;margin-bottom:20px}.kpi{margin:0}.number{font-size:34px;font-weight:750;color:#245cc7}.risk{color:#b45309;font-weight:700}p{white-space:pre-wrap;overflow-wrap:anywhere}.charts{grid-template-columns:repeat(2,minmax(0,1fr))}.chart{margin:0}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;border-bottom:1px solid #eef1f5;padding:10px 8px}th{color:#64758b;font-weight:600}.track{width:100%;height:12px;border-radius:4px;background:#edf2fa;display:block}.bar{height:12px;background:#3b73cf;display:block;border-radius:4px}.chart td:first-child{width:32%}.chart td:last-child{white-space:nowrap}a{color:#2563eb;text-decoration:none}.detail-table{overflow:auto}li{margin-bottom:8px}@media(max-width:760px){.kpis,.charts{grid-template-columns:1fr}header{padding:24px}h1{font-size:25px}main{padding:20px 12px}}@media print{body{background:white}section,header{break-inside:avoid}}</style></head>
<body><main><header><small>WATCHVULN AI · 全局风险研判</small><h1>{{.Report.Title}}</h1><div>统计周期：{{cnTime .Report.PeriodStart}} — {{cnTime .Report.PeriodEnd}}（结束时刻不含）</div><div>生成时间：{{cnTime .Report.CreatedAt}} · UTC+8 东八区</div></header>
<div class="kpis"><div class="kpi"><small>入选漏洞总数</small><div class="number">{{.Stats.Total}}</div></div><div class="kpi"><small>严重及高危 / 占比</small><div class="number">{{.Stats.High}} <span style="font-size:18px">/ {{printf "%.1f" .Stats.HighPercent}}%</span></div></div><div class="kpi"><small>总体风险级别</small><p class="risk">{{.Stats.Risk}}</p></div></div>
<section><h2>01 · 执行摘要</h2><p>{{.Analysis.Summary}}</p></section>
<div class="charts"><section class="chart"><h2>02 · 风险等级分布</h2><table aria-label="漏洞风险等级统计"><thead><tr><th>等级</th><th>占比</th><th>数量 / 比例</th></tr></thead><tbody>{{range .Stats.Severity}}<tr><td>{{.Label}}</td><td><span class="track"><span class="bar" style="width:{{printf "%.2f" .Percent}}%"></span></span></td><td>{{.Count}} / {{printf "%.1f" .Percent}}%</td></tr>{{end}}</tbody></table></section>
<section class="chart"><h2>03 · 受影响组件分类</h2><table aria-label="受影响组件统计"><thead><tr><th>组件</th><th>占比</th><th>数量 / 比例</th></tr></thead><tbody>{{range .Stats.Components}}<tr><td>{{.Label}}</td><td><span class="track"><span class="bar" style="width:{{printf "%.2f" .Percent}}%"></span></span></td><td>{{.Count}} / {{printf "%.1f" .Percent}}%</td></tr>{{end}}</tbody></table></section></div>
<section class="chart"><h2>04 · 每日入库趋势</h2><table aria-label="按东八区入库日期统计"><thead><tr><th>日期（UTC+8）</th><th>占周期总量比例</th><th>漏洞数量</th></tr></thead><tbody>{{range .Stats.Trend}}<tr><td>{{.Label}}</td><td><span class="track"><span class="bar" style="width:{{printf "%.2f" .Percent}}%"></span></span></td><td>{{.Count}}</td></tr>{{end}}</tbody></table></section>
<section><h2>05 · 重点风险与全局研判</h2><h3>优先关注</h3><ul>{{range .Analysis.Risks}}<li>{{.}}</li>{{end}}</ul><h3>整体分析</h3><p>{{.Analysis.Analysis}}</p><h3>管理建议</h3><ul>{{range .Analysis.Actions}}<li>{{.}}</li>{{end}}</ul></section>
<section><h2>06 · 漏洞索引与修复入口</h2><p class="muted">具体影响和修复方法请进入对应漏洞的详细信息页面查看。</p><div class="detail-table"><table><thead><tr><th>漏洞 / 组件</th><th>CVE</th><th>等级</th><th>详情与修复</th></tr></thead><tbody>{{range .Items}}<tr><td>{{.Title}}</td><td>{{.CVE}}</td><td>{{if .Severity}}{{.Severity}}{{else}}未知{{end}}</td><td><a href="{{$.BaseURL}}/vulnerabilities/{{.ID}}">详细信息</a></td></tr>{{end}}</tbody></table></div></section>
<section><h2>统计口径与局限</h2><p class="muted">统计仅覆盖所选周期内入库、筛选结果为通过的漏洞，按配置进行CVE去重。图表数据由程序计算，不由AI估算。等级沿用上游，缺失记为未知（共{{.Stats.Unknown}}条）；总体分级按入选最高已知等级作保守提示，不等同实际资产风险。组件依据标题与标签规则识别，未识别归入待确认。趋势为入库日期而非披露日期，缺失日期不代表上游当天无漏洞。AI解释仅供参考，需结合资产清单复核。</p></section></main></body></html>`))
